const rows = $input.all().map((i) => i.json).filter((r) => r && r.id);

const first = $input.first()?.json;
if (first && first.error) {
  return [{ json: { statusCode: 500, body: { message: 'No se pudo leer el catálogo de eventos.' } } }];
}

// Devolver [] y no [{}] cuando no hay filas: el frontend defiende igual, pero
// no hay razón para propagar la rareza de n8n al contrato de la API.
return [{ json: { statusCode: 200, body: rows.map((r) => ({
  ...r,
  payload_schema:               r.payload_schema ?? {},
  implementations:              Array.isArray(r.implementations) ? r.implementations : [],
  implementations_count:        Number(r.implementations_count ?? 0),
  active_implementations_count: Number(r.active_implementations_count ?? 0),
})) } }];
